-- A tutorial the account has read is not raised again (__WBTutorialFlagged: the server's flags).
function __WBLogin()
  local plateEnemies,plateFriends=__WB.plateEnemies,__WB.plateFriends
  local p = __WB.resolve("player")
  if p and p.skyrimXP then __WBInstallExperience() end
  if __WB.talents and __WB.installTalentApi and not __WBTalentApi then __WB.installTalentApi() end   -- a ReloadUI kept them
  if __WB.liveInventory and __WB.installBags then __WB.installBags() end
  if __WB.liveParty and __WB.installParty then __WB.installParty() end
  if __WB.liveTrainer and __WB.installTrainer then __WB.installTrainer() end
  if __WB.liveTaxi then __WBInstallTaxi() end
  if __WBInstallMounts then __WBInstallMounts() end
  for _, e in ipairs(LOGIN) do
    if e[1] ~= "TUTORIAL_TRIGGER" or not __WBTutorialFlagged(e[2]) then __WBFire(unpack(e, 1, table.maxn(e))) end
  end
  if (__WB.comboPoints or 0) > 0 then __WBFire("PLAYER_COMBO_POINTS") end -- retained live points after ReloadUI
  if __WB.liveParty then __WBFire("PARTY_MEMBERS_CHANGED") __WBFire("PARTY_LEADER_CHANGED") end
  if __WB.trainer then __WBFire("TRAINER_SHOW") end
  -- After the login burst: UIParent's UpdateNameplates runs during it. The retained live switches win on reload.
  if __WB.liveNameplates and __WB.installNameplates then
    __WB.plateEnemies,__WB.plateFriends=plateEnemies,plateFriends
    __WB.installNameplates()
  end
end
